(function(){
 'use strict';
 const M=window.MockEngine,bank=window.REVIEW_UNITS.flatMap(u=>u.questions).concat(window.REVIEW_EXAM_ITEMS||[]);
 let draft=null,paper=null,saveOK=true;
 const storageKey=p=>Learner.key()+':mock:'+p.id;
 function read(p){try{const d=JSON.parse(localStorage.getItem(storageKey(p)));return M.compatible(d,p,Learner.getName())?d:null;}catch{return null;}}
 function store(){try{localStorage.setItem(storageKey(paper),JSON.stringify(draft));saveOK=true;}catch{saveOK=false;}return saveOK;}
 function cards(){return window.REVIEW_EXAMS.filter(p=>p.grade===activeGrade).sort((a,b)=>['國語','數學','英語','自然','社會'].indexOf(a.subject)-['國語','數學','英語','自然','社會'].indexOf(b.subject)).map(p=>{const d=read(p);return `<article class="exam-card"><span class="eyebrow">${esc(p.publisher)}</span><h3>${esc(p.subject)}模擬考 A 卷</h3><p>${esc(p.scope)}</p><span class="exam-card-meta">20 題・100 分・建議 ${p.minutes} 分鐘</span><p>${d?.result?`上次完成：${d.result.score} 分`:d?`草稿：已答 ${20-M.missing(d).length} / 20 題`:'全卷答完，一次送出批改。'}</p><button class="primary" data-exam-open="${p.id}">${d?.result?'查看成績與解析':d?'繼續作答':'開始這份考卷'} →</button></article>`;}).join('');}
 function homeSection(){return `<section class="mock-home"><div class="section-head"><h2>整份模擬考<span>每科 100 分，整卷送出後才看答案。</span></h2><button class="secondary" data-exam-catalog>選擇模擬考卷 →</button></div></section>`;}
 function bindEntry(){main.querySelector('[data-exam-catalog]')?.addEventListener('click',()=>go('exams'));}
 function catalog(){draft=null;paper=null;renderGradePicker();main.innerHTML=`<section class="intro"><div><span class="eyebrow">READ · THINK · CHECK</span><h1>${gradeLabel(activeGrade)}期中模擬考</h1><p>每科一份 A 卷，20 題 × 5 分＝100 分。</p></div></section><section class="exam-intro"><h2>讀懂線索，再寫下你的答案。</h2><p>先讀文章、觀察圖表；可以來回檢查、修改答案。完成全部 20 題後，一次送出，才會顯示分數與解析。</p><p>計算題可用紙筆，再填數字。草稿依名字保存在這台裝置；建議時間不會倒數，也不會自動交卷。</p><p class="muted">依已核對的考試範圍與公開考題參考編選，難度以應用理解為主。閱讀材料為延伸文本；英語本卷不含聽力。<a href="assessment-sources.html" target="_blank" rel="noopener">查看題型參考 ↗</a></p></section><div class="exam-cards">${cards()}</div>`;main.querySelectorAll('[data-exam-open]').forEach(b=>b.onclick=()=>open(b.dataset.examOpen));}
 function open(id,fresh=false){
  if(!Learner.getName()){Learner.showName();return;}
  paper=window.REVIEW_EXAMS.find(p=>p.id===id&&p.grade===activeGrade);if(!paper)return;
  draft=fresh?null:read(paper);if(!draft){draft=M.create(paper,bank,Learner.getName(),Learner.uuid);draft.questions.forEach(q=>{const v=LearningVisuals.dataFor(q);if(v){q.visual=JSON.parse(JSON.stringify(v));const caption=q.visual.caption||'';q.visual.caption='題目附圖';if(q.visual.description?.startsWith(caption)&&caption)q.visual.description=q.visual.description.slice(caption.length).replace(/^[。．：\s]+/,'');}});store();}
  if(draft.result)record();render();focusMain();
 }
 function articleMarkup(q,id){return `<section class="reading-passage mock-article" id="${id}" aria-label="閱讀文章"><span class="eyebrow">閱讀文章與圖表</span><h2>${esc(q.passageTitle)}</h2>${q.glossary?`<details class="reading-glossary"><summary>閱讀小字典</summary><p>${esc(q.glossary)}</p></details>`:''}${q.passage.split(/\n\n/).map((p,i)=>`<p lang="${paper.subject==='英語'?'en':'zh-Hant'}">${esc(p)}</p>${i===0?LearningVisuals.markup(q):''}`).join('')}</section>`;}
 function questionMarkup(q,i,articleId){
  const done=!!draft.result,right=done&&draft.result.rows[i].correct,selected=draft.answers[q.id];
  return `<article class="mock-question" id="exam-question-${i}" tabindex="-1"><div class="mock-q-head"><span>第 ${i+1} 題・${esc(units[q.unit].name)}</span><span>${q.points} 分${done?`・得 ${draft.result.rows[i].points} 分`:''}</span></div>${articleId?`<a class="article-return" href="#${articleId}">回看本篇文章 ↑</a>`:''}${!q.passageId?(q.chart?chartMarkup(q.chart):'')+(q.figure?figureMarkup(q.figure):'')+LearningVisuals.markup(q):''}<h3>${esc(q.text.replace(/^〈[^〉]+〉/,'').replace(/^.*? · /,'').replace(/^第 \d+ 組[：:]/,''))}</h3>${q.type==='numeric'?`<div class="numeric-answer"><label for="exam-number-${i}">我的答案</label><div><input id="exam-number-${i}" data-exam-number="${i}" type="text" inputmode="decimal" autocomplete="off" maxlength="30" placeholder="填入數字" value="${esc(selected??'')}" ${done?'disabled':''}><span>${esc(q.unitLabel||'')}</span></div><small>先用紙筆計算，只填數字。</small></div>`:`<div class="options" role="group" aria-label="第 ${i+1} 題答案">${q.options.map((o,j)=>`<button type="button" class="option ${selected===j?'chosen':''} ${done&&q.answer===j?'correct':''} ${done&&selected===j&&!right?'incorrect':''}" data-exam-question="${i}" data-exam-option="${j}" aria-pressed="${selected===j}" ${done?'disabled':''}><span class="letter">${letters[j]}</span><span>${esc(o)}</span></button>`).join('')}</div>`}${done?`<div class="feedback ${right?'':'wrong'}"><strong>${right?'答對了，得到 5 分':'這題得到 0 分'}</strong><p>你的答案：${esc(selectionText(q,selected).join('、'))}${q.type==='numeric'?' '+esc(q.unitLabel||''):''}</p><p>正確答案：${esc(selectionText(q,q.answer).join('、'))}${q.type==='numeric'?' '+esc(q.unitLabel||''):''}</p><p>${esc(q.explanation)}</p>${questionSource(q)}</div>`:''}</article>`;
 }
 function body(){let n=0;return E.readingGroups(draft.questions).map(group=>{const id='exam-article-'+n++;return `<section class="mock-block ${group[0].passageId?'mock-reading-block':'mock-solo-block'}">${group[0].passageId?articleMarkup(group[0],id):''}<div class="mock-block-questions">${group.map(q=>questionMarkup(q,draft.questions.indexOf(q),group[0].passageId?id:null)).join('')}</div></section>`;}).join('');}
 function render(){
  window.studyInProgress=!draft.result;
  main.innerHTML=`<div class="mock-paper"><button class="back" id="exam-back">← 回到模擬考卷</button><section class="exam-title"><span class="eyebrow">${esc(paper.publisher)}・固定 A 卷</span><h1>${esc(paper.title)}</h1><p>${esc(Learner.getName())}的考卷・${esc(paper.scope)}</p><p>20 題，每題 5 分，滿分 100 分。${draft.result?'已交卷，可以查看整份解析。':'全部答完再送出；送出前都能修改。'}</p></section>${draft.result?`<section class="mock-result" aria-label="模擬考成績"><span>這次的成績</span><strong>${draft.result.score}<small> / 100 分</small></strong><p>答對 ${draft.result.right} / 20 題。${draft.result.score===100?'繼續保持讀題與檢查的好習慣。':'回到文章與圖表找線索，再看下面的解析。'}</p><div class="exam-breakdown">${paper.coverage.map(c=>{const rs=draft.result.rows.filter(r=>draft.questions.find(q=>q.id===r.id).unit===c.unit);return `<span>${esc(c.name)}：${rs.reduce((n,r)=>n+r.points,0)} / ${c.count*5} 分</span>`;}).join('')}</div><p id="exam-record-status" role="status">${draft.logged?'作答與成績已加入學習紀錄；同步狀態請見頁面上方。':'紀錄待保存，請保持頁面並再試一次。'}</p>${!draft.logged?'<button class="secondary" id="exam-record-retry">重試保存紀錄</button>':''}<button class="secondary" id="exam-again">重新作答相同 A 卷</button></section>`:''}<div class="exam-submit-bar"><div><strong id="exam-answered"></strong><a class="exam-nav-return" href="#exam-navigation">回到題號 ↑</a><small id="exam-save-status" role="status"></small></div>${draft.result?'<button class="secondary" id="exam-bottom-back">回到模擬考卷</button>':'<button class="primary" id="exam-submit">送出整份考卷，查看成績</button>'}</div><nav id="exam-navigation" class="exam-navigator" aria-label="考卷題號導覽">${draft.questions.map((q,i)=>`<a href="#exam-question-${i}" data-exam-jump="${i}" class="${draft.result?(draft.result.rows[i].correct?'exam-right':'exam-wrong'):E.ready(q,draft.answers[q.id])?'answered':''}" aria-label="第 ${i+1} 題${draft.result?(draft.result.rows[i].correct?'答對':'待訂正'):E.ready(q,draft.answers[q.id])?'已作答':'未作答'}">${i+1}</a>`).join('')}</nav><p class="exam-nav-help">點題號可跳到該題。${draft.result?'綠色為答對，橘色為待訂正。':'綠色表示已填答案，尚未批改。'}</p><p id="exam-validation" class="exam-validation" role="alert"></p>${body()}</div>`;
  document.querySelector('#exam-back').onclick=()=>go('exams');document.querySelector('#exam-bottom-back')?.addEventListener('click',()=>go('exams'));
  main.querySelectorAll('[data-exam-option]').forEach(b=>b.onclick=()=>{if(draft.result)return;const i=Number(b.dataset.examQuestion),q=draft.questions[i];draft.answers[q.id]=Number(b.dataset.examOption);main.querySelectorAll(`[data-exam-question="${i}"]`).forEach(o=>{const chosen=Number(o.dataset.examOption)===draft.answers[q.id];o.classList.toggle('chosen',chosen);o.setAttribute('aria-pressed',String(chosen));});store();update();});
  main.querySelectorAll('[data-exam-number]').forEach(input=>input.oninput=()=>{if(draft.result)return;draft.answers[draft.questions[Number(input.dataset.examNumber)].id]=input.value;store();update();});
  document.querySelector('#exam-submit')?.addEventListener('click',submit);
  document.querySelector('#exam-again')?.addEventListener('click',()=>{if(confirm('重新作答相同 A 卷？上次完成的成績與作答紀錄會保留。'))open(paper.id,true);});
  document.querySelector('#exam-record-retry')?.addEventListener('click',()=>{record();render();});update();
 }
 function update(){
  const missing=M.missing(draft),count=20-missing.length;const validation=document.querySelector('#exam-validation');if(validation)validation.textContent='';
  document.querySelector('#exam-answered').textContent=draft.result?`已交卷・${draft.result.score} / 100 分`:`已答 ${count} / 20 題`;
  document.querySelector('#exam-save-status').textContent=saveOK?'本機已保存・依名字保留進度':'無法暫存：請勿關閉頁面，並請家長協助釋放儲存空間。';
  if(!draft.result)main.querySelectorAll('[data-exam-jump]').forEach(a=>{const i=Number(a.dataset.examJump),ready=!missing.includes(i);a.classList.toggle('answered',ready);a.setAttribute('aria-label',`第 ${i+1} 題${ready?'已作答':'未作答'}`);});
 }
 function events(){const elapsed=Math.max(0,(draft.result.finishedAt-draft.startedAt)/1000),unitName=gradeLabel(paper.grade)+'｜'+paper.subject+'期中模擬考 A 卷';const common={sessionId:draft.sessionId,subject:paper.subject,unitName,grade:paper.grade,learner:draft.owner,createdAt:new Date(draft.result.finishedAt).toISOString()};return draft.questions.map((q,i)=>({...common,id:draft.sessionId+'-a-'+(i+1),kind:'answer',questionId:q.id,questionType:q.type,question:(q.passage?q.passageTitle+'\n'+q.passage+'\n':'')+(q.chart?JSON.stringify(q.chart)+'\n':'')+(q.figure?JSON.stringify(q.figure)+'\n':'')+LearningVisuals.logText(q)+q.text,selected:selectionText(q,draft.answers[q.id]),expected:selectionText(q,q.answer),correct:draft.result.rows[i].correct,elapsedSeconds:elapsed/20})).concat({...common,id:draft.sessionId+'-summary',kind:'session',right:draft.result.right,total:20,score:draft.result.score,elapsedSeconds:elapsed});}
 function record(){if(!draft.result||draft.logged||draft.owner!==Learner.getName())return;draft.events=draft.events||events();if(!store())return;if(Learner.logBatch(draft.events)){draft.logged=true;store();}}
 function submit(){
  if(draft.result)return;
  const missing=M.missing(draft);if(missing.length){const el=document.querySelector('#exam-validation');el.textContent=`還有 ${missing.length} 題未完成：${missing.map(i=>i+1).join('、')}。請全部答完後再送出。`;el.tabIndex=-1;el.scrollIntoView({block:'start',behavior:'instant'});el.focus({preventScroll:true});return;}
  draft.result=M.grade(draft);record();
  draft.result.rows.forEach(r=>{if(!r.correct&&!saved.mistakes.includes(r.id))saved.mistakes.push(r.id);else if(r.correct)saved.mistakes=saved.mistakes.filter(id=>id!==r.id);});persist();updateCount();render();focusMain();
 }
 window.MockExam={homeSection,bindEntry,catalog,reset:()=>{draft=null;paper=null;},active:()=>!!draft&&!draft.result};
})();
